import numpy as np, json
def f(g):
    g=np.array(g); H,W=g.shape
    out=g.copy()
    seen=np.zeros_like(g,bool)
    for y in range(H):
        for x in range(W):
            if g[y,x]==0 or seen[y,x]: continue
            # flood same color
            col=int(g[y,x]); stack=[(y,x)]; cells=[]
            seen[y,x]=True
            while stack:
                yy,xx=stack.pop(); cells.append((yy,xx))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=yy+dy,xx+dx
                    if 0<=ny<H and 0<=nx<W and g[ny,nx]==col and not seen[ny,nx]:
                        seen[ny,nx]=True; stack.append((ny,nx))
            ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
            y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
            if len(cells)!=(y1-y0+1)*(x1-x0+1): continue
            sub=out[y0:y1+1,x0:x1+1]
            for yy in range(sub.shape[0]):
                for xx in range(sub.shape[1]):
                    corner=(yy in(0,sub.shape[0]-1))and(xx in(0,sub.shape[1]-1))
                    edge=(yy in(0,sub.shape[0]-1))or(xx in(0,sub.shape[1]-1))
                    sub[yy,xx]= 1 if corner else (4 if edge else 2)
            out[y0:y1+1,x0:x1+1]=sub
    return out.tolist()
